                if value is target:
                    return True
                if isinstance(value, dict):
                    return any(
                        references_node(item, target)
                        for item in (*value.keys(), *value.values())
                    )
                if isinstance(value, (list, tuple, set, frozenset)):
                    return any(references_node(item, target) for item in value)
                try:
